package com.iminiapp.backend.dining.api;
import com.iminiapp.backend.dining.application.DiningReservationService;import com.iminiapp.backend.identity.web.CurrentPrincipal;import com.iminiapp.backend.shared.api.ApiResponse;import com.iminiapp.backend.shared.web.TraceIds;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.List;import static com.iminiapp.backend.dining.api.DiningModels.*;
@RestController @RequestMapping("/api/v1/dining") public class DiningReservationController{private final DiningReservationService s;public DiningReservationController(DiningReservationService s){this.s=s;}@PostMapping("/reservations")public ApiResponse<ReservationResponse> create(@RequestHeader("Idempotency-Key")String key,@RequestBody CreateReservationRequest b,HttpServletRequest r){return ApiResponse.success(s.create(CurrentPrincipal.from(r),key,b),TraceIds.from(r));}@GetMapping("/reservations")public ApiResponse<List<ReservationResponse>> mine(HttpServletRequest r){return ApiResponse.success(s.mine(CurrentPrincipal.from(r)),TraceIds.from(r));}@GetMapping("/reservations/{id}")public ApiResponse<ReservationResponse> detail(@PathVariable long id,HttpServletRequest r){return ApiResponse.success(s.mineDetail(CurrentPrincipal.from(r),id),TraceIds.from(r));}@PostMapping("/reservations/{id}/cancel")public ApiResponse<ReservationResponse> cancel(@PathVariable long id,HttpServletRequest r){return ApiResponse.success(s.cancel(CurrentPrincipal.from(r),id),TraceIds.from(r));}}
